      { start: 4.8, en: "Jill is learning the days of the week.", ipa: "/dʒɪl ɪz ˈlɜːrnɪŋ ðə deɪz əv ðə wiːk/", vi: "Jill đang học các ngày trong tuần." },
      { start: 9.0, en: "'Monday, Tuesday, Wednesday, Thursday, Friday, Saturday, and Sunday,' she chants with her dad on the way to daycare.", ipa: "/ˈmʌndeɪ ˈtuːzdeɪ ˈwɛnzdeɪ ˈθɜːrzdeɪ ˈfraɪdeɪ ˈsætərdeɪ ænd ˈsʌndeɪ ʃiː tʃænts wɪð hɜːr dæd ɒn ðə weɪ tuː ˈdeɪˌkɛər/", vi: "'Thứ Hai, Thứ Ba, Thứ Tư, Thứ Năm, Thứ Sáu, Thứ Bảy và Chủ Nhật,' cô bé nhẩm đọc cùng bố trên đường tới nhà trẻ." },
      { start: 20.5, en: "Dad tells her that Monday to Friday are week days.", ipa: "/dæd tɛlz hɜːr ðæt ˈmʌndeɪ tuː ˈfraɪdeɪ ɑːr wiːk deɪz/", vi: "Bố bảo rằng từ Thứ Hai đến Thứ Sáu là các ngày trong tuần." },
      { start: 26.0, en: "Children go to school. Parents go to work.", ipa: "/ˈtʃɪldrən ɡoʊ tuː skuːl. ˈpɛrənts ɡoʊ tuː wɜːrk/", vi: "Trẻ em đến trường, còn cha mẹ đi làm." },
      { start: 30.5, en: "But Saturday and Sunday are the weekend days.", ipa: "/bʌt ˈsætərdeɪ ænd ˈsʌndeɪ ɑːr ðə ˈwiːkˌɛnd deɪz/", vi: "Nhưng Thứ Bảy và Chủ Nhật là những ngày cuối tuần." },
      { start: 35.5, en: "At the end of the week, it's time to rest and play.", ipa: "/æt ði ɛnd əv ðə wiːk ɪts taɪm tuː rɛst ænd pleɪ/", vi: "Vào cuối tuần, đây là khoảng thời gian để nghỉ ngơi và vui chơi." },
      { start: 41.5, en: "Hooray! The weekend is on the way.", ipa: "/hʊˈreɪ! ðə ˈwiːkˌɛnd ɪz ɒn ðə weɪ/", vi: "Hoan hô! Cuối tuần đã đến rồi." }
