    sentences: [
      { start: 4.8, en: "Gary Groundhog lives under the ground all winter.", ipa: "/ˈɡɛəri ˈɡraʊndˌhɔːɡ lɪvz ˈʌndər ðə ɡraʊnd ɔːl ˈwɪntər/", vi: "Chú chũi đất Gary sống ẩn mình dưới lòng đất suốt cả mùa đông." },
      { start: 11.5, en: "In spring, Gary comes out of his hole in the ground.", ipa: "/ɪn sprɪŋ ˈɡɛəri kʌmz aʊt əv hɪz hoʊl ɪn ðə ɡraʊnd/", vi: "Đến mùa xuân, Gary chui ra khỏi chiếc hang của mình." },
      { start: 18.0, en: "Some people think he knows if winter is over.", ipa: "/sʌm ˈpiːpl θɪŋk hiː noʊz ɪf ˈwɪntər ɪz ˈoʊvər/", vi: "Nhiều người tin rằng chú biết rõ mùa đông đã kết thúc hay chưa." },
      { start: 23.5, en: "If he sees his shadow on the ground, that means winter is not over yet.", ipa: "/ɪf hiː siːz hɪz ˈʃædoʊ ɒn ðə ɡraʊnd ðæt miːnz ˈwɪntər ɪz nɒt ˈoʊvər jɛt/", vi: "Nếu chú nhìn thấy cái bóng của mình in trên mặt đất, điều đó có nghĩa mùa đông vẫn chưa qua đi." },
      { start: 32.5, en: "If he does not see his shadow, that means winter is over.", ipa: "/ɪf hiː dʌz nɒt siː hɪz ˈʃædoʊ ðæt miːnz ˈwɪntər ɪz ˈoʊvər/", vi: "Còn nếu chú không thấy cái bóng của mình, tức là mùa xuân đã về." },
      { start: 40.0, en: "Gary is happy when he does not see his shadow.", ipa: "/ˈɡɛəri ɪz ˈhæpi wɛn hiː dʌz nɒt siː hɪz ˈʃædoʊ/", vi: "Gary rất vui mừng mỗi khi không nhìn thấy cái bóng của mình." },
      { start: 46.5, en: "Is it spring yet?", ipa: "/ɪz ɪt sprɪŋ jɛt?/", vi: "Liệu đã sang mùa xuân thật chưa nhỉ?" }
    ]
